#!/usr/bin/env python3
from pathlib import Path
import subprocess,wave,math,struct,json
out=Path('output');out.mkdir(exist_ok=True)
audio=out/'narration.wav';video=out/'AI時短ラボ_01_完成版.mp4';sfx=out/'ui_sfx.wav';timing=out/'narration_timing.json'
if not audio.exists() or not timing.exists():raise SystemExit('Missing narration/timing')
FONT='/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc';REG='/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc'
with wave.open(str(audio),'rb') as w: dur=w.getnframes()/w.getframerate()
sr=44100;cues=[.1,2.7,5.4,8.1,11.2,14.5,17.5,20.5,23.5]
frames=bytearray(int(sr*(dur+.5))*2)
for c in cues:
 for j in range(int(.09*sr)):
  d=j/sr;v=math.sin(2*math.pi*900*d)*math.exp(-34*d)*.14;idx=(int(c*sr)+j)*2
  if idx+1<len(frames):struct.pack_into('<h',frames,idx,int(v*32767))
with wave.open(str(sfx),'wb') as w:w.setparams((1,2,sr,len(frames)//2,'NONE','not compressed'));w.writeframes(frames)
f=["drawbox=x=0:y=0:w=1080:h=1920:color=0x07111f:t=fill",f"drawtext=fontfile={FONT}:text='AI時短ラボ':fontcolor=0x6ee7ff:fontsize=32:x=60:y=70"]
# Fast visual story: proof -> source -> prompt -> result -> paste -> CTA
f += ["drawbox=x=60:y=245:w=960:h=920:color=0xf8fafc:t=fill:enable='between(t,0,2.7)'",f"drawtext=fontfile={FONT}:text='手入力':fontcolor=0xff5f6d:fontsize=48:x=130:y=330:enable='between(t,0,2.7)'",f"drawtext=fontfile={FONT}:text='→ AIで表に':fontcolor=0x22c55e:fontsize=58:x=560:y=330:enable='between(t,0,2.7)'",f"drawtext=fontfile={REG}:text='山田様 / 090... / 10月1日':fontcolor=0x172033:fontsize=38:x=110:y=540:enable='between(t,0,2.7)'",f"drawtext=fontfile={FONT}:text='氏名   電話   日時  ✓':fontcolor=0x172033:fontsize=45:x=540:y=720:enable='between(t,.35,2.7)'",f"drawtext=fontfile={FONT}:text='3秒で意味がわかる':fontcolor=0xffe45e:fontsize=52:x=(w-text_w)/2:y=1050:enable='between(t,.6,2.7)'"]
f += ["drawbox=x=70:y=245:w=940:h=980:color=white:t=fill:enable='between(t,2.7,7.8)'",f"drawtext=fontfile={FONT}:text='バラバラな顧客情報':fontcolor=0xff5f6d:fontsize=52:x=115:y=320:enable='between(t,2.7,7.8)'",f"drawtext=fontfile={REG}:text='山田太郎 / 090-0000-1111':fontcolor=0x172033:fontsize=40:x=120:y=510:enable='between(t,2.7,7.8)'",f"drawtext=fontfile={REG}:text='yamada@example.com / 10月1日14時':fontcolor=0x172033:fontsize=34:x=120:y=600:enable='between(t,3.2,7.8)'",f"drawtext=fontfile={REG}:text='佐藤花子 / 080-2222-3333':fontcolor=0x172033:fontsize=40:x=120:y=790:enable='between(t,3.8,7.8)'",f"drawtext=fontfile={REG}:text='satou@example.com / 10月2日10時':fontcolor=0x172033:fontsize=34:x=120:y=880:enable='between(t,4.3,7.8)'",f"drawtext=fontfile={FONT}:text='これを1件ずつ？':fontcolor=0xffb020:fontsize=58:x=(w-text_w)/2:y=1080:enable='between(t,5,7.8)'"]
f += ["drawbox=x=65:y=235:w=950:h=1040:color=0x101d31:t=fill:enable='between(t,7.8,14.8)'",f"drawtext=fontfile={FONT}:text='AI Assistant':fontcolor=0x70f0b1:fontsize=48:x=115:y=305:enable='between(t,7.8,14.8)'","drawbox=x=110:y=465:w=860:h=500:color=0x1d304b:t=fill:enable='between(t,7.8,14.8)'",f"drawtext=fontfile={REG}:text='元の文章を貼る':fontcolor=white:fontsize=40:x=150:y=535:enable='between(t,7.8,14.8)'",f"drawtext=fontfile={REG}:text='氏名・電話・メール・希望日時を':fontcolor=white:fontsize=37:x=150:y=650:enable='between(t,9,14.8)'",f"drawtext=fontfile={FONT}:text='表にして':fontcolor=0xffe45e:fontsize=70:x=150:y=760:enable='between(t,10.2,14.8)'",f"drawtext=fontfile={FONT}:text='送信 ▶':fontcolor=0x70f0b1:fontsize=48:x=735:y=1020:enable='between(t,11.4,14.8)'",f"drawtext=fontfile={REG}:text='※画面はイメージ':fontcolor=white@0.45:fontsize=25:x=735:y=1210:enable='between(t,7.8,14.8)'"]
f += [f"drawtext=fontfile={FONT}:text='生成結果':fontcolor=0x70f0b1:fontsize=58:x=80:y=270:enable='between(t,14.8,21.5)'","drawbox=x=55:y=420:w=970:h=720:color=white:t=fill:enable='between(t,14.8,21.5)'","drawbox=x=55:y=420:w=970:h=115:color=0x1f6feb:t=fill:enable='between(t,14.8,21.5)'",f"drawtext=fontfile={FONT}:text='氏名      電話番号       希望日時':fontcolor=white:fontsize=38:x=95:y=458:enable='between(t,14.8,21.5)'",f"drawtext=fontfile={REG}:text='山田太郎  090-0000-1111  10/1 14時':fontcolor=0x172033:fontsize=35:x=80:y=640:enable='between(t,15.2,21.5)'",f"drawtext=fontfile={REG}:text='佐藤花子  080-2222-3333  10/2 10時':fontcolor=0x172033:fontsize=35:x=80:y=785:enable='between(t,15.8,21.5)'",f"drawtext=fontfile={FONT}:text='整理完了 ✓':fontcolor=0x22c55e:fontsize=64:x=(w-text_w)/2:y=1040:enable='between(t,16.5,21.5)'"]
f += [f"drawtext=fontfile={FONT}:text='Excelへ':fontcolor=white:fontsize=62:x=(w-text_w)/2:y=285:enable='between(t,21.5,{dur})'","drawbox=x=60:y=430:w=960:h=650:color=white:t=fill:enable='between(t,21.5,26.5)'",f"drawtext=fontfile={FONT}:text='コピー → ⌘V':fontcolor=0x172033:fontsize=70:x=(w-text_w)/2:y=650:enable='between(t,21.5,23.5)'",f"drawtext=fontfile={FONT}:text='貼り付け完了 ✓':fontcolor=0x22c55e:fontsize=70:x=(w-text_w)/2:y=800:enable='between(t,23.5,26.5)'",f"drawtext=fontfile={FONT}:text='明日会社で使うなら':fontcolor=white:fontsize=58:x=(w-text_w)/2:y=570:enable='gte(t,26.5)'",f"drawtext=fontfile={FONT}:text='保存して試す':fontcolor=0xffe45e:fontsize=82:x=(w-text_w)/2:y=720:enable='gte(t,26.5)'",f"drawtext=fontfile={REG}:text='毎日1つ、仕事がラクになるAI術':fontcolor=0x70f0b1:fontsize=40:x=(w-text_w)/2:y=880:enable='gte(t,26.5)'"]
# Narration-synced subtitles from exact generated chunk timing.
for i,x in enumerate(json.loads(timing.read_text(encoding='utf-8'))):
 a=x['start'];b=x['end'];txt=x['text'].replace("'","’").replace(':','\\:').replace(',','，')
 size=50 if len(txt)>20 else 58
 f += [f"drawbox=x=70:y=1450:w=940:h=205:color=black@0.78:t=fill:enable='between(t,{a},{b})'",f"drawtext=fontfile={FONT}:text='{txt}':fontcolor={'0xffe45e' if i in (0,4,9) else 'white'}:fontsize={size}:x=(w-text_w)/2:y=1510:enable='between(t,{a},{b})'"]
f += ["drawbox=x='120+mod(t*300,760)':y=1110:w=24:h=24:color=0xffe45e:t=fill:enable='between(t,3,24)'",f"drawbox=x=0:y=1875:w='min(1080,1080*t/{max(dur,1):.3f})':h=10:color=0x38d9ff:t=fill"]
fg=','.join(f)
cmd=['ffmpeg','-y','-f','lavfi','-i',f'color=c=0x07111f:s=1080x1920:r=30:d={dur+.2:.3f}','-i',str(audio),'-i',str(sfx),'-filter_complex',f"[0:v]{fg}[v];[1:a]volume=1.0[voice];[2:a]volume=0.28[fx];[voice][fx]amix=inputs=2:duration=first:normalize=0[a]",'-map','[v]','-map','[a]','-c:v','libx264','-preset','ultrafast','-crf','20','-threads','0','-pix_fmt','yuv420p','-c:a','aac','-b:a','160k','-ar','44100','-shortest','-movflags','+faststart',str(video)]
subprocess.run(cmd,check=True);print(video)
